(()=>{'use strict';const Q=window.Q={};Q.$=(s,r=document)=>r.querySelector(s);Q.$$=(s,r=document)=>[...r.querySelectorAll(s)];Q.esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));Q.plain=v=>new DOMParser().parseFromString(String(v??''),'text/html').body.textContent||'';
Q.get=(k,d=null)=>{try{const v=localStorage.getItem(k);return v===null?d:JSON.parse(v);}catch{return d;}};Q.set=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{Q.toast(Q.t('storageError'));return false;}};Q.raw=(k,d='')=>{try{return localStorage.getItem(k)||d;}catch{return d;}};Q.rawSet=(k,v)=>{try{localStorage.setItem(k,v);return true;}catch{Q.toast(Q.t('storageError'));return false;}};
Q.lang=['en','bn','ja'].includes(Q.raw('fqLang'))?Q.raw('fqLang'):'en';Q.t=k=>window.WORDS?.[Q.lang]?.[k]||window.WORDS?.en?.[k]||k;Q.toast=s=>{const e=Q.$('#toast');if(e){e.textContent=s;e.hidden=false;clearTimeout(Q.toastTimer);Q.toastTimer=setTimeout(()=>e.hidden=true,7000);}};Q.unbox=x=>x?.result??x?.data??x;
Q.db=new Promise((resolve,reject)=>{const r=indexedDB.open('famous-quran-v2',1);r.onupgradeneeded=()=>r.result.createObjectStore('items');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});Q.db.catch(()=>{});Q.idb=async(op,key,value)=>{const db=await Q.db;return new Promise((resolve,reject)=>{const tx=db.transaction('items',op==='get'||op==='keys'?'readonly':'readwrite'),s=tx.objectStore('items');const r=op==='keys'?s.getAllKeys():op==='put'?s.put(value,key):op==='delete'?s.delete(key):s.get(key);tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});};
const flights=new Map();Q.json=async url=>{if(flights.has(url))return flights.get(url);const task=(async()=>{const saved=await Q.idb('get','api:'+url).catch(()=>null);if(!navigator.onLine&&saved)return saved.value;const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),14000);try{const r=await fetch(url,{signal:ac.signal,headers:{Accept:'application/json'}});if(!r.ok)throw Error('HTTP '+r.status);const value=await r.json();await Q.idb('put','api:'+url,{value,at:Date.now(),source:url}).catch(()=>{});return value;}catch(e){if(saved){Q.cachedFallback=true;return saved.value;}throw e;}finally{clearTimeout(timer);}})();flights.set(url,task);try{return await task;}finally{flights.delete(url);}};
Q.shuffle=xs=>{const a=[...xs];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};Q.unique=xs=>[...new Map(xs.map(x=>[String(x.id),x])).values()];Q.saved=()=>{const x=Q.get('fqHadithFav',[]);return Array.isArray(x)?x.map(String):[];};Q.favs=()=>{const x=Q.get('fqFav',[]);return Array.isArray(x)?x:[];};Q.notify=()=>window.dispatchEvent(new Event('fq:saved'));Q.download=(blob,name)=>{const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);};
Q.saveMedia=async(url,label,type='audio')=>{const key='media:'+url,old=await Q.idb('get',key);if(old)return old;const parsed=new URL(url,location.href);if(parsed.protocol!=='https:'||!/(^|\.)(islamic\.network|mp3quran\.net)$/.test(parsed.hostname))throw Error('Unsupported media source');const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),120000),limit=100*1024*1024;try{const r=await fetch(url,{signal:ac.signal,mode:'cors'});if(r.status!==200)throw Error('Complete media download unavailable');const mime=r.headers.get('Content-Type')||'';if(!/^(audio|video)\//.test(mime)&&!mime.includes('octet-stream'))throw Error('Not a media file');if(+r.headers.get('Content-Length')>limit)throw Error('File exceeds 100 MB');const reader=r.body.getReader(),parts=[];let size=0;while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>limit){await reader.cancel();throw Error('File exceeds 100 MB');}parts.push(value);}const blob=new Blob(parts,{type:mime}),record={url,label,type,blob,bytes:blob.size,at:Date.now()};if(!blob.size)throw Error('Empty file');await Q.idb('put',key,record);return record;}finally{clearTimeout(timer);}};
Q.stop=()=>{document.querySelectorAll('#clips iframe').forEach(f=>f.remove());document.querySelectorAll('#clips [data-embed]').forEach(b=>b.disabled=false);document.querySelectorAll('audio,video').forEach(a=>a.pause());if(Q.objectURL){URL.revokeObjectURL(Q.objectURL);Q.objectURL=null;}};Q.play=async(el,url)=>{Q.stop();const saved=await Q.idb('get','media:'+url).catch(()=>null);Q.objectURL=saved?URL.createObjectURL(saved.blob):null;el.src=Q.objectURL||url;try{await el.play();}catch{Q.toast(Q.t('playFailed'));}};Q.error=(el,e)=>{console.warn('Famous Quran:',e?.message||e);el.textContent=Q.t('sourceError');};})();
